// Mini intérprete de rangos: solo ^ y ~ con tres números (sin pre-lanzamientos)
const numeros = (v) => v.split('.').map(Number);
const comparar = (a, b) => a[0] - b[0] || a[1] - b[1] || a[2] - b[2];

function limites(rango) {
  const operador = rango[0];
  const [M, m, p] = numeros(rango.slice(1));
  const desde = [M, m, p]; // incluido
  let hasta; // excluido
  if (operador === '~') hasta = [M, m + 1, 0];
  else if (M > 0) hasta = [M + 1, 0, 0];
  else if (m > 0) hasta = [0, m + 1, 0];
  else hasta = [0, 0, p + 1];
  return { desde, hasta };
}

function cumple(version, rango) {
  const { desde, hasta } = limites(rango);
  const v = numeros(version);
  return comparar(v, desde) >= 0 && comparar(v, hasta) < 0;
}

